function attempt(read) {
  try {
    return String(read());
  } catch (error) {
    return error.name;
  }
}

const parseInt = (text) => text.length;

console.log(attempt(() => stock));
console.log(attempt(() => globalThis.stock));

globalThis.stock = 12;

console.log(attempt(() => stock + 1));
console.log(parseInt("250"));
console.log(globalThis.parseInt("250"));
